document.querySelector('.menu')?.addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');if(!open)document.querySelector('.mega')?.removeAttribute('open')});
document.querySelector('#motion-toggle')?.addEventListener('click',e=>{const paused=document.body.classList.toggle('motion-paused');e.currentTarget.textContent=paused?'모션 재생':'모션 일시정지';e.currentTarget.setAttribute('aria-pressed',paused)});
document.querySelectorAll('[data-resource]').forEach(b=>b.addEventListener('click',()=>location.href=b.dataset.resource+'.html'));
const form=document.querySelector('#prototype-form');
if(form){const service=new URLSearchParams(location.search).get('service');for(const input of form.querySelectorAll('[name=service]'))if(input.value===service)input.checked=true;let step=1;
function show(n,moveFocus=true){step=n;form.querySelectorAll('[data-step]').forEach(el=>{const active=+el.dataset.step===n;el.hidden=!active;el.querySelectorAll('input,select,textarea,button').forEach(control=>control.disabled=!active)});document.querySelectorAll('.form-progress li').forEach((el,i)=>{el.classList.toggle('active',i+1===n);if(i+1===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});const panel=form.querySelector(`[data-step="${n}"]`);if(moveFocus&&panel){const heading=panel.querySelector('h2,h3')||panel;heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
}
function advance(){const selected=[...form.querySelectorAll('[name=service]:checked')];if(!selected.length){document.querySelector('#form-error').textContent='관심 항목을 한 개 이상 선택해 주세요.';const first=form.querySelector('[name=service]');first?.setAttribute('aria-describedby','form-error');first?.focus();return}document.querySelector('#form-error').textContent='';document.querySelector('#selected-summary').textContent='선택한 항목: '+selected.map(e=>e.parentElement.querySelector('b').textContent).join(', ');show(2)}
form.querySelectorAll('[name=service]').forEach(input=>input.addEventListener('change',()=>document.querySelector('#form-error').textContent=''));
form.querySelector('#form-next').addEventListener('click',advance);form.querySelector('.back-step').addEventListener('click',()=>show(1));form.querySelectorAll('input[required]:not([type=checkbox])').forEach(input=>input.addEventListener('input',()=>input.setCustomValidity('')));form.addEventListener('submit',e=>{e.preventDefault();if(step===1){advance();return}if(step!==2)return;form.querySelectorAll('input[required]:not([type=checkbox])').forEach(input=>input.setCustomValidity(input.value.trim()?'':'내용을 입력해 주세요.'));if(form.reportValidity())show(3)});show(1,false);}
document.querySelector('#calculator-form')?.addEventListener('submit',e=>{e.preventDefault();const employees=document.querySelector('#employees'),mealBudget=document.querySelector('#meal-budget');const count=Number(employees.value),budget=Number(mealBudget.value),method=document.querySelector('#meal-method')?.value||'기타';employees.setCustomValidity(Number.isSafeInteger(count)&&count>0?'':'직원 수를 1명 이상의 정수로 입력해 주세요.');mealBudget.setCustomValidity(Number.isFinite(budget)&&budget>=0&&Number.isSafeInteger(count*budget)?'':'식대 금액을 확인해 주세요.');if(!e.currentTarget.reportValidity())return;const result=document.querySelector('#calculator-result');result.replaceChildren();const eyebrow=document.createElement('p');eyebrow.className='eyebrow';eyebrow.textContent='우리 회사의 월 식대 예산';const h=document.createElement('h2');h.textContent=(count*budget).toLocaleString('ko-KR')+'원 / 월';const p=document.createElement('p');const guidance={'법인카드':'카드 배부, 영수증 취합과 직원별 사용 내역을 관리하는 과정을 살펴보세요.','종이식권':'식권 제작·분배·회수와 식당별 정산 업무를 모바일로 정리하는 방식을 살펴보세요.','급여 포함 지급':'회사의 식대 지급 기준과 사용 내역을 함께 관리하는 방식을 살펴보세요.','구내식당':'외부 제휴점과 배달식사로 근무 장소·시간에 맞는 선택지를 넓혀 보세요.','기타':'지급 기준 설정, 사용 내역 자동 기록, 통합 정산으로 운영을 점검해 보세요.'};p.textContent=count.toLocaleString('ko-KR')+'명 × 1인당 '+budget.toLocaleString('ko-KR')+'원 · 현재 '+method+'. '+(guidance[method]||guidance['기타']);const note=document.createElement('p');note.className='prototype-note';note.textContent='입력값 기준 월 예산을 확인하는 프로토타입입니다. 실제 절감액을 의미하지 않으며 절감률은 적용하지 않습니다.';const link=document.createElement('a');link.href='consult.html?service=sikdae';link.className='button dark';link.textContent='우리 회사에 맞는 식사복지 상담 ↗';result.append(eyebrow,h,p,note,link);h.setAttribute('tabindex','-1');h.focus({preventScroll:true});result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});
document.querySelectorAll('#calculator-form input').forEach(input=>input.addEventListener('input',()=>input.setCustomValidity('')));
document.querySelector('#content-search')?.addEventListener('input',e=>{let count=0;document.querySelectorAll('.editorial-row').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(e.target.value.trim().toLowerCase());if(!row.hidden)count++});document.querySelector('.search-empty').hidden=count>0});
function closePrototypeMenu(){document.querySelector('.mega')?.removeAttribute('open');document.querySelector('nav')?.classList.remove('open');document.querySelector('.menu')?.setAttribute('aria-expanded','false');document.querySelector('.menu')?.setAttribute('aria-label','메뉴 열기')}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const mobileOpen=document.querySelector('nav')?.classList.contains('open'),megaOpen=document.querySelector('.mega')?.open;closePrototypeMenu();if(mobileOpen)document.querySelector('.menu')?.focus();else if(megaOpen)document.querySelector('.mega summary')?.focus()}});
document.querySelectorAll('header nav a').forEach(a=>a.addEventListener('click',closePrototypeMenu));
document.addEventListener('click',e=>{if(!e.target.closest('header'))closePrototypeMenu()});
matchMedia('(max-width: 1000px)').addEventListener('change',closePrototypeMenu);
const prototypeNav=document.querySelector('header nav');if(prototypeNav){prototypeNav.id||='site-navigation';document.querySelector('.menu')?.setAttribute('aria-controls',prototypeNav.id)}
